import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import vm from 'node:vm';
import {assertPublicStagingApproved} from './public-asset-policy.mjs';

// Synthetic names only; no game media is read or generated by these tests.
test('only reviewed media, explicit runtime paths and authored content are candidates',()=>{
 assert.doesNotThrow(()=>assertPublicStagingApproved([]));
 assert.doesNotThrow(()=>assertPublicStagingApproved(['source/js/ginka-reading.js','source/_posts/article.md']));
 for(const name of ['source/images/random.png','source/voice-config.json','source/js/renderer-v2.js','astro/vendor-assets/live2d/model.json']){
  assert.throws(()=>assertPublicStagingApproved([name]),/Unapproved/);
 }
});
test('pending original scene paths fail closed including separator and case variants',()=>{
 for(const file of ['source/images/ginka/scenes/fake.webp','SOURCE/IMAGES/GINKA/SCENES/fake.png','source\\images\\ginka\\scenes\\fake.webp']){
  assert.throws(()=>assertPublicStagingApproved([file]),/Public asset staging blocked: 1 tracked path/);
 }
});
test('diagnostics are bounded and make no staging writes',()=>{
 const fake=Array.from({length:48},(_,i)=>`source/images/ginka/scenes/fake-${i}.webp`);
 assert.throws(()=>assertPublicStagingApproved(fake),error=>{
  assert.match(error.message,/48 tracked path/);assert.match(error.message,/and 43 more/);
  assert.match(error.message,/No staging writes were made/);assert.doesNotMatch(error.message,/fake-47/);return true;
 });
 const source=fs.readFileSync(new URL('./prepare.mjs',import.meta.url),'utf8');
 const start=source.indexOf('const root='),end=source.indexOf('function copy(',start),writes=[];
 assert.ok(start>=0&&end>start);
 assert.throws(()=>vm.runInNewContext(source.slice(start,end),{
  path,project:path.resolve('/fixture/astro'),
  fs:{rmSync:(...args)=>writes.push(args),mkdirSync:(...args)=>writes.push(args)},
  execFileSync:()=>fake.join('\0'),assertPublicStagingApproved
 }),/Public asset staging blocked/);
 assert.deepEqual(writes,[]);
});
test('renamed media cannot bypass its reviewed content hash',()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'ginka-public-policy-'));
 try{
  fs.mkdirSync(path.join(root,'source/images'),{recursive:true});
  fs.writeFileSync(path.join(root,'source/images/avatar.png'),'synthetic, not reviewed bytes');
  assert.throws(()=>assertPublicStagingApproved(['source/images/avatar.png'],root),/Reviewed media hash changed/);
 }finally{fs.rmSync(root,{recursive:true,force:true});}
});
test('symlink directories and files are rejected before public copy',()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'ginka-public-symlink-'));
 try{
  fs.mkdirSync(path.join(root,'real'));fs.writeFileSync(path.join(root,'real/article.md'),'fixture');
  fs.mkdirSync(path.join(root,'source'));
  fs.symlinkSync(path.join(root,'real'),path.join(root,'source/_posts'),process.platform==='win32'?'junction':'dir');
  assert.throws(()=>assertPublicStagingApproved(['source/_posts/article.md'],root),/Symlink\/junction/);
 }finally{fs.rmSync(root,{recursive:true,force:true});}
});
